// MentionTexts resolves the new and pre-mutation rich text scanned for mentions, preferring
// each JSON candidate over its plain-text fallback only when it is valid slate text
func MentionTexts(payload MutationPayload, spec MentionSpec) (string, string) {
	newText, _ := payload.StringValue(spec.DetailsField)

	if raw, ok := payload.Value(spec.DetailsJSONField); ok {
		if candidate := jsonx.Stringify(raw); candidate != "" && slateparser.IsValidSlateText(candidate) {
			newText = candidate
		}
	}

	oldText, _ := payload.OldStringValue(spec.DetailsField)

	if raw, ok := payload.OldValue(spec.DetailsJSONField); ok {
		if candidate := jsonx.Stringify(raw); candidate != "" && slateparser.IsValidSlateText(candidate) {
			oldText = candidate
		}
	}

	return newText, oldText
}

// MentionedUsers resolves the user ids newly mentioned between the old and new rich text
func MentionedUsers(ctx context.Context, client *generated.Client, oldText, newText, objectType, objectID, objectName string) ([]string, error) {
	newMentions := slateparser.GetNewMentions(oldText, newText, objectType, objectID, objectName)
	if len(newMentions) == 0 {
		return nil, nil
	}

	mentionedOrgMemberIDs := slateparser.ExtractMentionedOrgMemberIDs(newMentions)
	if len(mentionedOrgMemberIDs) == 0 {
		return nil, nil
	}

	userIDs, err := client.OrgMembership.Query().
		Where(orgmembership.IDIn(mentionedOrgMemberIDs...)).
		Select(orgmembership.FieldUserID).
		Strings(ctx)
	if err != nil {
		logx.FromContext(ctx).Error().Err(err).Msg("failed to get user IDs from org membership IDs")
		return nil, err
	}

	return userIDs, nil
}

// GroupMemberUserIDs returns the user ids of all members of the given group
func GroupMemberUserIDs(ctx context.Context, client *generated.Client, groupID string) ([]string, error) {
	return client.Group.Query().
		Where(group.IDEQ(groupID)).
		QueryUsers().
		IDs(ctx)
}

// mentionRecipients builds the recipients resolver for one mention-annotated schema,
// excluding the owning actor from the mentioned users
func mentionRecipients(spec MentionSpec) func(Invocation, MutationPayload, json.RawMessage) ([]string, error) {
	return func(inv Invocation, payload MutationPayload, row json.RawMessage) ([]string, error) {
		newText, oldText := MentionTexts(payload, spec)
		if newText == "" {
			return nil, nil
		}

		userIDs, err := MentionedUsers(inv.Context, inv.Client, oldText, newText, payload.MutationType, payload.EntityID, inv.Schema.DisplayValue(row))
		if err != nil {
			return nil, err
		}

		ownerID := FieldValue(row, spec.OwnerField)

		return lo.Filter(userIDs, func(id string, _ int) bool {
			return id != ownerID
		}), nil
	}
}

// approvalRecipients builds the recipients resolver for one approval-annotated schema,
// resolving the approver group's members from the loaded row
func approvalRecipients(spec ApprovalSpec) func(Invocation, MutationPayload, json.RawMessage) ([]string, error) {
	return func(inv Invocation, _ MutationPayload, row json.RawMessage) ([]string, error) {
		approverID := FieldValue(row, spec.ApproverField)
		if approverID == "" {
			logx.FromContext(inv.Context).Info().Msg("approver not set for entity entering approval")
			return nil, nil
		}

		userIDs, err := GroupMemberUserIDs(inv.Context, inv.Client, approverID)
		if err != nil {
			logx.FromContext(inv.Context).Error().Err(err).Str("group_id", approverID).Msg("failed to get approver group")
			return nil, err
		}

		if len(userIDs) == 0 {
			logx.FromContext(inv.Context).Warn().Str("group_id", approverID).Msg("no users found in approver group")
		}

		return userIDs, nil
	}
}

// MentionListeners returns one declarative mention listener per mention-annotated schema,
// excluding the skip schemas; the caller owns the notification content and capability hook
func MentionListeners(concern MutationConcern, caller func(*auth.Caller, MutationPayload) *auth.Caller, content NotificationContent, skip ...*Schema) []gala.Registration {
	registrations := []gala.Registration{}

	for _, schema := range AllSchemas() {
		if schema.MentionSpec == nil || lo.Contains(skip, schema) {
			continue
		}

		registrations = append(registrations, MutationListener{
			Concern: concern,
			Schema:  schema,
			Caller:  caller,
			Notify: &NotifySpec{
				Recipients: mentionRecipients(*schema.MentionSpec),
				Content:    content,
			},
		})
	}

	return registrations
}

// ApprovalListeners returns one declarative approval listener per approval-annotated schema,
// gated on the schema's status field matching any of the trigger values; the caller owns the
// notification content, trigger vocabulary, and capability hook
func ApprovalListeners(concern MutationConcern, caller func(*auth.Caller, MutationPayload) *auth.Caller, content NotificationContent, statusValues []string, skip ...*Schema) []gala.Registration {
	registrations := []gala.Registration{}

	for _, schema := range AllSchemas() {
		if schema.ApprovalSpec == nil || lo.Contains(skip, schema) {
			continue
		}

		registrations = append(registrations, MutationListener{
			Concern: concern,
			Schema:  schema,
			Match:   []FieldMatch{{Field: schema.ApprovalSpec.StatusField, In: statusValues}},
			Caller:  caller,
			Notify: &NotifySpec{
				Recipients: approvalRecipients(*schema.ApprovalSpec),
				Content:    content,
			},
		})
	}

	return registrations
}
